INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(26901, 'Romans 4:12', 'Romans', 4, 12, '&nbsp;او هغه د سنت شوو خلقو هم نيکۀ دے نۀ يواځې دا چې سنت شوى دى، بلکې چې زمونږ د نيکۀ اِبراهيم غوندې ايمان ولرى، يعنې هغه ايمان چې اِبراهيم لا د سنت کېدلو نه مخکښې لرلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26902, 'Romans 4:13', 'Romans', 4, 13, '&nbsp;خُدائ پاک د اِبراهيم او د هغۀ اولاد سره د دُنيا د وارث کېدو لوظ په شريعت د عمل کولو په وسيله ونۀ کړو بلکې د صداقت په بنياد يې وکړو چې په ايمان حاصليږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26903, 'Romans 4:14', 'Romans', 4, 14, '&nbsp;ځکه کۀ هغوئ د شريعت په وسيله وارثان کيږى نو بيا ايمان بې‌ځايه دے او وعده بې‌فائدې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26904, 'Romans 4:15', 'Romans', 4, 15, '&nbsp;ځکه چې شريعت خو سزا اعلانوى، خو چرته چې شريعت نشته نو هلته د شريعت ماتول هم نشته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26905, 'Romans 4:16', 'Romans', 4, 16, '&nbsp;نو خُدائ پاک د خپل فضل په مطابق دا وعده ځکه وکړه چې اِبراهيم په هغۀ ايمان راوړے وو، د دې دپاره چې د هغۀ فائده د اِبراهيم ټول نسل ته د بخښنې په طور ورسى. نۀ يواځې د هغوئ دپاره چې په شريعت قائم دى، بلکې د هغوئ دپاره هم چې د اِبراهيم په شان ايمان لرى، ځکه چې هغه زمونږ د ټولو پلار دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26906, 'Romans 4:17', 'Romans', 4, 17, '&nbsp;لکه چې صحيفې وائى چې، ”ما تۀ د ډېرو قومونو پلار جوړ کړے يې.“ د هغه خُدائ پاک په حضور کښې په چا چې د هغۀ ايمان وو، څوک چې مړى بيا راژوندى کوى او نشت شتۀ کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26907, 'Romans 4:18', 'Romans', 4, 18, '&nbsp;بيا هغۀ په نااُميدۍ کښې اُميد وساتلو، او د هغۀ دا ايمان وو چې هغه به د ډېرو قومونو پلار شى، د هغه کلام په مطابق چې هغۀ ته وئيلے شوے وو چې، ”ستا اولاد به بې‌شمېره وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26908, 'Romans 4:19', 'Romans', 4, 19, '&nbsp;د ايمان د څۀ کمزورۍ نه بغېر هغۀ د خپل وجود لکه د مړى په شان کمزورۍ ته فکر ونۀ کړو ځکه چې هغه خواوشا د سلو کالو بوډا وو او ساره هم شنډه وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26909, 'Romans 4:20', 'Romans', 4, 20, '&nbsp;خو هغه د خُدائ پاک په لوظ شکمن نۀ شو بلکې په خپل ايمان کښې نور هم مضبوط شو او خُدائ پاک ته يې جلال ورکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26910, 'Romans 4:21', 'Romans', 4, 21, '&nbsp;هغه په دې خبره پوره مطمئن وو چې خُدائ پاک خپل کړے لوظ پوره کولے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26911, 'Romans 4:22', 'Romans', 4, 22, '&nbsp;نو ځکه دا ايمان اِبراهيم ته په صداقت حساب شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26912, 'Romans 4:23', 'Romans', 4, 23, '&nbsp;دا خبرې چې هغه صادق وګڼلے شو يواځې د اِبراهيم دپاره نۀ وې ليکلے شوې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26913, 'Romans 4:24', 'Romans', 4, 24, '&nbsp;بلکې زمونږ دپاره هم وې ځکه چې هغه به مونږ هم صادق وګڼى کۀ مونږ په هغۀ ايمان وساتو چا چې زمونږ مالِک عيسىٰ له مړو نه بيا راژوندے کړو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26914, 'Romans 4:25', 'Romans', 4, 25, '&nbsp;هغه څوک چې زمونږ د نافرمانو په وجه مرګ ته حواله شو او زمونږ د صادق کولو دپاره بيا راژوندے شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26915, 'Romans 5:1', 'Romans', 5, 1, '&nbsp;په دې وجه کله نه چې مونږ د ايمان په وسيله صادق کړے شُو نو د مالِک عيسىٰ مسيح په وسيله د خُدائ پاک سره زمونږ صُلح ده،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26916, 'Romans 5:2', 'Romans', 5, 2, '&nbsp;د چا په وسيله چې مونږ د خُدائ پاک په فضل کښې هغه ځائ وموندو چرته چې اوس مونږ يُو، او مونږ د خُدائ پاک د لويئ په اُميد کښې خوشحالى کوُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26917, 'Romans 5:3', 'Romans', 5, 3, '&nbsp;نۀ صرف دا بلکې مونږ په خپلو تکليفونو هم خوشحالى کوُو، ځکه چې مونږ ته دا معلومه ده چې تکليفونه د برداشت طاقت پېدا کوى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26918, 'Romans 5:4', 'Romans', 5, 4, '&nbsp;او برداشت نه اخلاق پېدا کيږى، او اخلاق نه اُميد پېدا کيږى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26919, 'Romans 5:5', 'Romans', 5, 5, '&nbsp;او دا اُميد مونږ شرمېدو ته نۀ پرېږدى، ځکه چې د خُدائ پاک مينه زمونږ په زړونو کښې د هغه روحُ القُدس په وسيله اچولے شوې ده کوم چې مونږ ته راکړے شوے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26920, 'Romans 5:6', 'Romans', 5, 6, '&nbsp;ځکه کله چې مونږ لا بې‌وسه وُو، نو مسيح په صحيح وخت کښې د بې‌دينو دپاره خپل ځان قربان کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26921, 'Romans 5:7', 'Romans', 5, 7, '&nbsp;د يو صادق انسان دپاره به په مشکله څوک خپل ځان قربان کړى. خو کېدے شى چې د يو نېک او مهربانه کس دپاره څوک خپل ځان قربان کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26922, 'Romans 5:8', 'Romans', 5, 8, '&nbsp;خو خُدائ پاک خپله مينه مونږ ته داسې ثابته کړه، چې کله مونږ لا په ګناه کښې اخته وُو نو مسيح زمونږ دپاره مړ شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26923, 'Romans 5:9', 'Romans', 5, 9, '&nbsp;مونږ چې د مسيح د وينې په وسيله صادقان شُو، نو دا نوره هم يقينى شوه چې مونږ به د هغۀ په وسيله د خُدائ پاک د غضب نه هم بچ شُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26924, 'Romans 5:10', 'Romans', 5, 10, '&nbsp;ځکه چې کله مونږ د خُدائ پاک دشمنان وُو نو مونږ د هغۀ د زوئ د مرګ په وسيله ورسره رضا شُو، او د دې نه زيات، د هغۀ د زوئ د ژوند په وسيله به بچ شُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26925, 'Romans 5:11', 'Romans', 5, 11, '&nbsp;خو مونږ د دې نه زيات د خپل مالِک عيسىٰ مسيح په وسيله په خُدائ پاک فخر کوُو د چا په وسيله چې مونږ د خُدائ پاک سره رضا شوى يُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26926, 'Romans 5:12', 'Romans', 5, 12, '&nbsp;نو څنګه چې ګناه د يو انسان په وسيله دُنيا ته راغله، او د ګناه په وسيله مرګ راغلو. او دغه شان مرګ په ټول انسانى نسل قبضه وکړه، ځکه چې ټولو بنى آدمو ګناه وکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26927, 'Romans 5:13', 'Romans', 5, 13, '&nbsp;د شريعت نه وړاندې ګناه دُنيا ته راغلې وه، خو چې کله شريعت نۀ وى نو ګناه هم ګناه نۀ حسابيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26928, 'Romans 5:14', 'Romans', 5, 14, '&nbsp;خو د آدم نه تر موسىٰ پورې مرګ په دُنيا غالب وو په هغه چا هم چې د آدم په شان ګناه يې نۀ وه کړې، آدم د راتلونکى عيسىٰ دپاره يو نمونه وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26929, 'Romans 5:15', 'Romans', 5, 15, '&nbsp;خو د آدم د نافرمانۍ او د خُدائ پاک په فضل کښې لوئ فرق دے. ځکه چې د دې يو انسان يعنې د آدم نافرمانۍ په ټولو مرګ نازل کړو خو د خُدائ پاک فضل او بخښنه د دې نه لويه ده ځکه چې د يو انسان يعنې عيسىٰ مسيح په وسيله يې هر چا ته ورکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26930, 'Romans 5:16', 'Romans', 5, 16, '&nbsp;او بيا دا چې د خُدائ پاک د فضل او د آدم د نافرمانۍ په نتيجه کښې غټ فرق دے ځکه چې د آدم نافرمانۍ دُنيا مجرمه کړه، کۀ څۀ هم چې مونږ ډېر ګناه ګار وُو خو د خُدائ پاک فضل مونږ د هغۀ سره پخلا کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26931, 'Romans 5:17', 'Romans', 5, 17, '&nbsp;کۀ چرې د يو سړى په نافرمانۍ د مرګ بادشاهى شوه، نو د خُدائ پاک فضل به د دې په مقابله کښې ډېر زيات وى او د هغۀ د صداقت بخښنه به ژوندون وى، د هغه يو سړى په وسيله چې عيسىٰ مسيح دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26932, 'Romans 5:18', 'Romans', 5, 18, '&nbsp;نو بيا دا چې د يو سړى د نافرمانۍ په وجه ټول خلق مجرمان شول نو د يو سړى د صداقت په وجه ټول خلق راستباز کېدے شى او ژوندون هم حاصلولے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26933, 'Romans 5:19', 'Romans', 5, 19, '&nbsp;ځکه چې د يو سړى په نافرمانۍ ډېر ګناه ګار شول نو هم دغه شان د يو سړى په فرمانبردارۍ به ډېر صادقان هم شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26934, 'Romans 5:20', 'Romans', 5, 20, '&nbsp;خو شريعت ځکه راغلو چې خلقو ته پته ولګى چې هغوئ څومره ګناهګار دى. خو چرته چې نافرمانى زياته شى نو هلته فضل د هغې نه نور هم زيات شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26935, 'Romans 5:21', 'Romans', 5, 21, '&nbsp;ځکه څنګه چې ګناه د مرګ په وسيله خپله بادشاهى قائمه کړه، دغه شان د خُدائ پاک فضل هم د صداقت په وسيله خپله بادشاهى کوى چې د مالِک عيسىٰ مسيح په وسيله مونږ د تل ژوندون طرف ته بوځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26936, 'Romans 6:1', 'Romans', 6, 1, '&nbsp;نو بيا مونږ په دې کښې څۀ ووايو؟ ولې مونږ دې په ګناهونو کښې اخته يُو د دې دپاره چې فضل نور هم زيات شى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26937, 'Romans 6:2', 'Romans', 6, 2, '&nbsp;نه، هيڅکله نه. مونږ خو ګناه ته مړۀ شوى يُو نو بيا څنګه په ګناه کښې ژوند تېرولے شُو؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26938, 'Romans 6:3', 'Romans', 6, 3, '&nbsp;ولې تاسو ته پته نشته چې کله مونږ ټولو په عيسىٰ مسيح کښې بپتسمه واخسته نو مونږ د هغۀ په مرګ کښې هم شامل شُو؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26939, 'Romans 6:4', 'Romans', 6, 4, '&nbsp;نو ځکه مونږ د هغۀ سره په بپتسمه کښې ښخ شُو او ورسره مړۀ شُو، نو چې څنګه مسيح د پلار په جلال کښې د مړو نه راپورته شو نو مونږ هم په نوى ژوندون کښې ورسره شامل شُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26940, 'Romans 6:5', 'Romans', 6, 5, '&nbsp;نو کۀ مونږ د هغۀ په مرګ کښې د هغۀ سره شامل يُو نو بيا به مونږ د هغۀ سره په نوې ژوندون کښې هم شامل يُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26941, 'Romans 6:6', 'Romans', 6, 6, '&nbsp;مونږ په دې پوهه يُو چې زمونږ زوړ انسانيت د مسيح سره په سولۍ کړے شو نو په مونږ کښې د ګناه اثر ختم شو او نور د ګناه په قبضه کښې نۀ يُو او د دې دپاره چې مونږ نور د ګناه غلامان نۀ شُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26942, 'Romans 6:7', 'Romans', 6, 7, '&nbsp;ځکه هر څوک چې مړ شى نو هغه د ګناه د اثر نه آزاد شى', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26943, 'Romans 6:8', 'Romans', 6, 8, '&nbsp;خو کۀ مونږ د مسيح سره مړۀ شُو نو زمونږ هم دا ايمان دے چې مونږ به د هغۀ سره ژوندى شُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26944, 'Romans 6:9', 'Romans', 6, 9, '&nbsp;مونږ ته دا معلومه ده چې مسيح د مړو نه بيا ژوندے شوے دے، او بيا به هيڅکله مړ نۀ شى، او د مرګ په هغۀ باندې نور هيڅ واک اختيار نشته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26945, 'Romans 6:10', 'Romans', 6, 10, '&nbsp;کله چې هغه مړ شو نو هغه د ټولو د ګناه دپاره يو ځل مړ شو خو اوس چې هغه ژوندے دے خُدائ پاک ته د جلال ورکولو دپاره ژوندے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26946, 'Romans 6:11', 'Romans', 6, 11, '&nbsp;نو تاسو هم خپل ځانونه ګناه ته مړۀ وګڼئ او په عيسىٰ مسيح کښې په شاملېدو سره يې خُدائ پاک ته ژوندى وګڼئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26947, 'Romans 6:12', 'Romans', 6, 12, '&nbsp;نو ځکه تاسو خپل ځان ګناه ته مۀ پرېږدئ چې په تاسو حکومت وکړى او چې تاسو د نفس تابع کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26948, 'Romans 6:13', 'Romans', 6, 13, '&nbsp;نور تاسو د خپل وجود اندامونه ګناه ته د بدکارۍ د ساز و سامان په طور مۀ وړاندې کوئ بلکې خپل ځانونه خُدائ پاک ته وړاندې کړئ د هغوئ په شان څوک چې د مرګ نه بيا راژوندى شوى دى، او خپل اندامونه خُدائ پاک ته د صداقت د ساز و سامان په طور وړاندې کړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
