(26991, 'Romans 8:8', 'Romans', 8, 8, '&nbsp;څوک چې د ګناه د فطرت په مطابق اوسيږى، هغوئ خُدائ پاک رضا کولے نۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26992, 'Romans 8:9', 'Romans', 8, 9, '&nbsp;خو تاسو د ګناه فطرت پسې نۀ يئ روان بلکې روح پسې روان يئ، ځکه چې د خُدائ پاک روح په تاسو کښې اوسى. او په چا کښې چې د مسيح روح نۀ وى نو هغه د مسيح نۀ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26993, 'Romans 8:10', 'Romans', 8, 10, '&nbsp;خو کۀ چرې مسيح په تاسو کښې اوسى نو کۀ څۀ هم ستاسو وجود د ګناه په وجه مړ شى، خو روح تاسو ته ژوند درکوى ځکه چې روح تاسو د خُدائ پاک سره رضا کړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26994, 'Romans 8:11', 'Romans', 8, 11, '&nbsp;کۀ چرې د خُدائ پاک روح په تاسو کښې وى چا چې عيسىٰ د مړو نه بيا ژوندے کړے دے، نو چا چې مسيح د مړو نه بيا ژوندے کړے دے هغه به ستاسو فانى وجودونو ته هم نوے ژوند ورکړى، د خپل هغه روح په وسيله چې په تاسو کښې اوسى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26995, 'Romans 8:12', 'Romans', 8, 12, '&nbsp;نو بيا اے زما وروڼو او خوېندو، په مونږ اوس د ګناه د اختيار هيڅ حق پاتې نۀ شو چې مونږ دې ته مجبور کړى چې مونږ د ګناه په فطرت کښې ژوند تېر کړُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26996, 'Romans 8:13', 'Romans', 8, 13, '&nbsp;ځکه کۀ چرې تاسو د ګناه د فطرت په مطابق ژوند تېر کړئ نو تاسو به مړۀ شئ، خو کۀ چرې د روح په وسيله تاسو د وجود خواهشات مړۀ کړئ نو تاسو به ژوندى پاتې شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26997, 'Romans 8:14', 'Romans', 8, 14, '&nbsp;ځکه چې هر څوک چې د خُدائ پاک د روح په هدايت چليږى، هغوئ د خُدائ پاک بچى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26998, 'Romans 8:15', 'Romans', 8, 15, '&nbsp;ځکه چې تاسو هغه روح نۀ دے حاصل کړے چې تاسو بيا د يرې غلامان کړى، بلکې تاسو د بچو جوړېدو هغه روح حاصل کړو چې د دې په وسيله مونږ ”ابا“ يعنې ”پلار“ وايو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26999, 'Romans 8:16', 'Romans', 8, 16, '&nbsp;دا هغه روح دے چې په خپله زمونږ روح سره دا ګواهى ورکوى چې مونږ د خُدائ پاک بچى يُو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27000, 'Romans 8:17', 'Romans', 8, 17, '&nbsp;او چې بچى يُو نو وارثان هم يُو. مونږ د خُدائ پاک وارثان او د مسيح په ميراث کښې شريک هم يُو، خو کۀ چرې مونږ د هغۀ سره په جلال کښې شريک يُو نو د هغۀ په تکليف کښې به هم شريک يُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');